// Lektionen 37–42 (Offenbarungsreihenfolge, Kairoer Chronologie) – erste lange Suren
window.LEKTIONEN7 = [
// ───────────────────────── Lektion 37: Al-Qamar ─────────────────────────
{
sure: 54, offb: 37, name: "Al-Qamar", arab: "سُورَةُ الْقَمَرِ", de: "Der Mond", verse: 55, ort: "Mekka",
zeit: "Mittelmekkanisch – nach dem Wunder der Mondspaltung, das die Mekkaner selbst sahen und dennoch „Zauberei“ nannten",
kurz: "Die Sure beginnt mit einem Ereignis, das Augenzeugen der Sahāba bezeugt haben: „Die Stunde ist nahegerückt, und der Mond hat sich gespalten.“ Die Mekkaner verlangten ein Zeichen – und sahen den Mond in zwei Hälften, mit dem Berg Ḥirāʾ dazwischen. Ihre Antwort: „Fortlaufende Zauberei!“ Daran zeigt die Sure ihr Thema: Nicht Beweise fehlen den Leugnern, sondern Bereitschaft. Es folgen fünf Untergangsgeschichten (Nūḥ, ʿĀd, Ṯamūd, Lūṭ, Pharao) – jede mit demselben Doppel-Refrain: „Wie waren da Meine Strafe und Meine Warnungen?“ und – viermal – der Satz, der diese ganze App begründet: „Und Wir haben den Koran zum Bedenken leicht gemacht. Aber gibt es jemanden, der bedenkt?“ Das Ende gehört den Gottesfürchtigen: „in Gärten und Bächen, auf dem Sitz der Wahrhaftigkeit, bei einem allmächtigen König.“",
schluessel: {arab: "وَلَقَدْ يَسَّرْنَا الْقُرْآنَ لِلذِّكْرِ فَهَلْ مِن مُّدَّكِرٍ", ueb: "Und Wir haben den Koran ja leicht gemacht zum Bedenken. Aber gibt es jemanden, der bedenkt?", ref: "54:17 (viermal in der Sure)"},
kontext: ["Die Mondspaltung ist durch mehrere Gefährten sahih bezeugt: Anas berichtet, die Mekkaner verlangten vom Propheten ﷺ ein Zeichen – „da zeigte er ihnen den Mond in zwei Teilen, so dass sie den (Berg) Ḥirāʾ zwischen den beiden sahen“ (Sahih al-Buchari, Nr. 3637; Sahih Muslim, Nr. 2802). Ibn Masʿūd: „Der Mond spaltete sich zur Zeit des Gesandten Allahs ﷺ in zwei Teile, und der Prophet ﷺ sagte: Bezeugt es!“ (Sahih al-Buchari, Nr. 3636; Sahih Muslim, Nr. 2800). Die Reaktion der Quraisch dokumentiert Vers 2: „Und wenn sie ein Zeichen sehen, wenden sie sich ab und sagen: fortlaufende Zauberei (siḥr mustamirr).“",
"Damit stellt die Sure die Schlüsselfrage der Daʿwa: Was bringt ein Wunder, wenn das Herz nicht will? Ihre Antwort: Nicht noch größere Zeichen – sondern Geschichte. Fünf Völker, die ihre Warner der Lüge bezichtigten, werden im Schnelldurchlauf vorgeführt, jede Episode auf ihre dramatischste Pointe verdichtet: die Arche „aus Planken und Nägeln“, der Eiswind über ʿĀd, „der die Menschen herausriss wie entwurzelte Palmstümpfe“, die Kamelstute als „Prüfung“ für Ṯamūd (vgl. Lektion 26), der eine „Schrei“, der sie „wie dürres Zeug des Pferchbauers“ machte, die geblendeten Augen der Leute Lūṭs, Pharaos Griff durch den „übermächtigen Greifer“.",
"Der viermalige Refrain ist die wichtigste Zusage dieser Sure für dich als Lernenden: yassarnā – Allah selbst hat den Koran „leicht gemacht“ zum Verstehen, Merken und Beherzigen. Kein anderes Buch der Weltliteratur wird von Millionen auswendig getragen, von Kindern wie Greisen, Arabern wie Nicht-Arabern. Die Frage „fa-hal min muddakir – gibt es jemanden, der bedenkt?“ ist eine offene Einladung: Die Tür ist leicht – wer tritt ein?"],
asbab: [
 {text: "Vers 1–2: die Mondspaltung auf Verlangen der Mekkaner – „Bezeugt es!“", quelle: "Sahih al-Buchari, Nr. 3636–3638; Sahih Muslim, Nr. 2800–2802"},
 {text: "Vers 47–48 („Die Übeltäter befinden sich in Irrtum und Wahnsinn … Kostet die Berührung von Saqar!“): herabgesandt im Zusammenhang mit den Quraisch, die über die Vorherbestimmung (qadar) stritten.", quelle: "Sahih Muslim, Nr. 2656 (Abū Huraira)"}
],
begriffe: [
 {arab: "انشَقَّ الْقَمَر", tr: "inschaqqa l-qamar", wurzel: "sch-q-q", erkl: "„Der Mond hat sich gespalten“ – Perfektform: ein geschehenes Ereignis, kein Zukunftsbild (so die Mufassirūn einhellig mit den Hadithen). Eines der großen sichtbaren Wunder des Propheten ﷺ – und zugleich Vorzeichen: „Die Stunde ist nahegerückt.“"},
 {arab: "مُسْتَمِرّ", tr: "mustamirr", wurzel: "m-r-r", erkl: "„Fortlaufend/andauernd“ – das Schutzschild-Wort der Leugner: Wenn ALLES ‚fortlaufende Zauberei' ist, muss man nie hinschauen. Moderne Varianten: ‚alles Manipulation', ‚alles Propaganda' – Pauschalverdacht als Denkverweigerung."},
 {arab: "مُزْدَجَر", tr: "muzdadschar", wurzel: "z-dsch-r", erkl: "54:4: „Zu ihnen ist doch von den Berichten gekommen, was reichlich Abschreckung enthält (muzdadschar)“ – zadschara: abhalten, zurückschrecken. Die Geschichten des Korans sind keine Unterhaltung, sondern Leitplanken."},
 {arab: "يَسَّرْنَا", tr: "yassarnā", wurzel: "y-s-r", erkl: "„Wir haben leicht gemacht“ – dieselbe Wurzel wie yusr (Lektion 12). Die Leichtigkeit des Korans ist göttliche Absicht: leicht zu rezitieren, zu memorieren, zu verstehen (im Kernanliegen) – die Einstiegshürde hat Allah selbst abgebaut."},
 {arab: "مُدَّكِر", tr: "muddakir", wurzel: "dh-k-r", erkl: "„Einer, der bedenkt/sich erinnern lässt“ – von tadhakkara. Die Frage fa-hal min muddakir ist offen formuliert wie eine Ausschreibung: Gesucht wird nicht der Gelehrte, sondern der Bedenkende. Jeder Leser kann sich melden."},
 {arab: "مَقْعَد صِدْق", tr: "maqʿad ṣidq", wurzel: "ṣ-d-q", erkl: "54:55: „auf dem Sitz der Wahrhaftigkeit, bei einem allmächtigen König“ – der Ehrenplatz der Muttaqīn: ein Sitz ohne Lüge, ohne Wackeln, in der Gegenwart des Königs (malīk muqtadir). Das letzte Wort der Sure ist Allahs Allmacht – nach 54 Versen über zerbrochene Völker sitzt der Gottesfürchtige sicher."}
],
tafsir: [
 {vers: "Verse 1–8", text: "Mondspaltung, Abwendung der Leugner („sie folgen ihren Neigungen – doch jede Angelegenheit kommt zum Ziel“, 54:3) und der Blick auf den Tag, an dem „der Rufer zu etwas Entsetzlichem ruft“: Sie kommen aus den Gräbern „mit demütigen Blicken, als wären sie ausschwärmende Heuschrecken“ (vgl. die Motten in Lektion 30). Ibn Kathīr zu 54:3: „Jede Sache kommt zum Ziel“ – Wahrheit setzt sich durch, Lüge läuft aus; ein Trostsatz für jede Epoche, in der die Lüge lauter ist."},
 {vers: "Verse 9–22: Nūḥ und ʿĀd", text: "Nūḥ wurde der Lüge bezichtigt, bedroht („gesteinigt wirst du!“) – „da rief er seinen Herrn an: Ich bin überwältigt, so hilf! (annī maġlūbun fa-ntaṣir)“. Die Antwort: Himmelstore voll Wasser, Quellen aus der Erde – „und das Wasser traf sich nach einer festgesetzten Angelegenheit“. Die Arche „aus Planken und Nägeln (dhāti alwāḥin wa-dusur) fuhr vor Unseren Augen – als Lohn für den, dem Undank entgegengebracht worden war.“ As-Saʿdī: ‚Vor Unseren Augen' – unter Allahs direkter Obhut: Wer für Allah verworfen wird, wird von Allah getragen. Dann ʿĀd: ein „durchgehend unheilvoller Tag“, der eiskalte Wind (ṣarṣar), Menschen „herausgerissen wie Stümpfe entwurzelter Palmen“. Nach jeder Episode: „Wie waren Meine Strafe und Meine Warnungen? Und Wir haben den Koran leicht gemacht zum Bedenken – gibt es einen, der bedenkt?“ – Strafbericht und Gnadenangebot im Wechseltakt."},
 {vers: "Verse 23–42: Ṯamūd, Lūṭ, Pharao", text: "Ṯamūd höhnte: „Einem menschlichen Einzelnen aus unseren Reihen sollen wir folgen?“ – das Dauerargument gegen Propheten (Standesdünkel). Die Kamelstute kommt ausdrücklich „als Prüfung (fitnatan) für sie – so warte ab und sei standhaft“; die Wasserteilung („jeder Trinkanteil zu fester Zeit“) testet schlichte Vertragstreue. Der „Genosse“ (ṣāḥibuhum) greift zu – ein Schrei, „und sie waren wie das dürre, zertretene Zeug des Pferchbauers“. Lūṭs Leute „wollten sogar seine Gäste“ – „da löschten Wir ihre Augen aus“. Pharaos Sippe: „Sie erklärten alle Unsere Zeichen für Lüge, da ergriffen Wir sie mit dem Griff eines Übermächtigen, Allmächtigen.“ – Al-Qurṭubī: Fünf Völker, fünf verschiedene Sünden (Spott, Hochmut, Vertragsbruch, Schamlosigkeit, Staatstyrannnei) – EIN Muster: takdhīb, die Leugnung der Warner. Die Sure fragt die Quraisch (V. 43): „Sind eure Ungläubigen etwa besser als jene? Oder habt ihr einen Freibrief in den Schriften?“"},
 {vers: "Verse 43–55", text: "„Oder sagen sie: Wir sind eine Schar, die sich gegenseitig hilft? Die Schar wird geschlagen werden, und sie werden den Rücken kehren!“ – Dieser Vers kam in Mekka herab, als die Muslime schwach waren; ʿUmar sagte später: Ich wusste nicht, welche Schar gemeint war – „bis ich den Propheten ﷺ am Tag von Badr im Panzer sah, wie er rezitierte: Die Schar wird geschlagen werden …“ (Sahih al-Buchari, Nr. 4875): Prophezeiung, Jahre vor Badr erfüllt. Dann die Qadar-Verse: „Wir haben alles nach Maß erschaffen (innā kulla schaiʾin chalaqnāhu bi-qadar), und Unser Befehl ist nur ein einziges (Wort), wie ein Augenblick.“ – mit dem Muslim-Hadith (Nr. 2656) als Anlass: Antwort an die, die über die Vorherbestimmung streiten. Schluss: Die Gottesfürchtigen „in Gärten und Bächen, auf dem Sitz der Wahrhaftigkeit bei einem allmächtigen König“ – das Buch der Untergänge endet mit dem sichersten Sitzplatz des Universums."}
],
ahadith: [
 {text: "Ibn Masʿūd: „Der Mond spaltete sich zur Zeit des Gesandten Allahs ﷺ in zwei Teile … und er sagte: Bezeugt es!“ / Anas: … so dass sie den Berg Ḥirāʾ zwischen den beiden Hälften sahen.", quelle: "Sahih al-Buchari, Nr. 3636–3638; Sahih Muslim, Nr. 2800–2802"},
 {text: "ʿUmars Bericht über Badr: Der Prophet ﷺ rezitierte im Panzer „Die Schar wird geschlagen werden, und sie werden den Rücken kehren“ – die Erfüllung von 54:45.", quelle: "Sahih al-Buchari, Nr. 4875 (vgl. 3953)"},
 {text: "„Alles ist nach Maß (bestimmt) – sogar die Schwäche und die Tüchtigkeit.“ – zu 54:49.", quelle: "Sahih Muslim, Nr. 2655"},
 {text: "Der Prophet ﷺ rezitierte in den beiden Festgebeten „Qāf“ und „Iqtarabati s-sāʿa“ (diese Sure).", quelle: "Sahih Muslim, Nr. 891"}
],
hanafi: null,
umsetzung: [
 "Nimm die yassarnā-Zusage persönlich: Wenn dir Koranlernen ‚zu schwer' vorkommt, widerspricht dir Allah viermal in einer Sure. Starte ein kleines Ḥifẓ-Projekt (z. B. diese Sure selbst – ihr Refrain trägt dich durch).",
 "Beantworte die offene Frage: fa-hal min muddakir – werde konkret ‚einer, der bedenkt': Nach jeder gelesenen Geschichte dieser App EINEN Satz notieren: Was war das Muster, und wo droht es mir?",
 "Entlarve das mustamirr-Muster bei dir selbst: Wo wischst du unbequeme Wahrheiten mit einem Pauschal-Label weg (‚alles übertrieben', ‚alles Panikmache')? Einmal bewusst hinschauen statt labeln.",
 "Merke dir maqʿad ṣidq als Ziel-Bild: Bei Statusangst und Platzhirsch-Spielen im Alltag – der einzige Sitzplatz, der zählt, ist ‚beim allmächtigen König'. Arbeite für diesen Platz."
]
},

// ───────────────────────── Lektion 38: Ṣād ─────────────────────────
{
sure: 38, offb: 38, name: "Ṣād", arab: "سُورَةُ صٓ", de: "Ṣād", verse: 88, ort: "Mekka",
zeit: "Mittelmekkanisch – als die Quraisch-Führer bei Abū Ṭālib gegen den Propheten ﷺ intervenierten",
kurz: "Die Sure der geprüften Könige und des ersten Hochmuts. Anlass: Die Quraisch-Elite zog zu Abū Ṭālib, dem Onkel des Propheten ﷺ – er solle seinen Neffen stoppen. Dessen Angebot „Sagt: lā ilāha illa llāh“ quittierten sie mit dem Satz, den die Sure zitiert: „Macht er die Götter zu einem einzigen Gott? Das ist fürwahr etwas Verwunderliches!“ Als Antwort führt die Sure drei Propheten-Könige vor, die zeigen, wie man mit Macht und Prüfung umgeht: Dāwūd, der nach dem Gleichnis der zwei Streitenden sofort seinen Fehler erkennt und sich niederwirft (Sadschda-Vers!), Sulaimān, der nach der Ablenkung durch seine edlen Pferde umkehrt und betet „Mein Herr, vergib mir und schenke mir eine Herrschaft…“, und Ayyūb, der Krankheit und Verlust trägt – alle drei mit demselben Ehrentitel: awwāb, „immer wieder (zu Allah) Umkehrender“. Das Gegenbild am Ende: Iblīs, der sich aus Stolz nicht beugte – „Ich bin besser als er.“ Zwischen Umkehr und Hochmut entscheidet sich alles.",
schluessel: {arab: "نِعْمَ الْعَبْدُ ۖ إِنَّهُ أَوَّابٌ", ueb: "Welch trefflicher Diener! Er war immer wieder umkehrend (awwāb).", ref: "38:30 u. 38:44"},
kontext: ["Den Anlass überliefert at-Tirmidhī (Nr. 3232, von Ibn ʿAbbās; als zuverlässig eingestuft): Die Vornehmen der Quraisch – unter ihnen Abū Dschahl – gingen zu Abū Ṭālib: „Dein Neffe schmäht unsere Götter…“ Der Prophet ﷺ sagte zu ihnen: „Ich will von euch nur EIN Wort, mit dem ihr die Araber beherrschen und die Nichtaraber euch unterwerfen würdet: Sagt lā ilāha illa llāh.“ Da standen sie auf: „Einen einzigen Gott? …“ – und dazu kamen die Anfangsverse von Ṣād herab: „… Macht er denn die Götter zu einem einzigen Gott? Das ist fürwahr etwas Verwunderliches! Und ihre Vornehmen gingen fort: Geht hin und haltet an euren Göttern fest …“ (38:5–6).",
"Die drei Königsgeschichten antworten auf einen unausgesprochenen Einwand: Die Quraisch-Führer fürchteten um ihre Macht. Die Sure zeigt: Der Islam ist nicht gegen Macht – Dāwūd und Sulaimān hatten mehr davon als ganz Mekka; aber Macht wird nur dann nicht zum Fluch, wenn ihr Träger awwāb ist: korrekturfähig, umkehrbereit, anbetend. Dāwūd korrigiert ein Fehlurteil in Sekunden; Sulaimān opfert, was ihn vom Dhikr ablenkte; Ayyūb bleibt im Verlust Diener.",
"Die Schluss-Szene (38:71–85) erzählt den Urknall des Hochmuts: Iblīs verweigert die Niederwerfung vor Ādam – „Ich bin besser als er: Du hast mich aus Feuer erschaffen, ihn aus Lehm.“ Der erste Rassist der Geschichte argumentiert mit Herkunftsmaterial. Genau diese Logik („wir, die Herren von Quraisch, sollen einem Waisenkind folgen?“) hatte die Sure in Vers 8 schon bei den Mekkanern dokumentiert: „Wurde die Ermahnung ausgerechnet auf IHN unter uns herabgesandt?“ – Hochmut ist immer dieselbe Krankheit, nur die Kostüme wechseln."],
asbab: [
 {text: "Verse 1–8: der Gang der Quraisch-Delegation zu Abū Ṭālib und das Wort des Propheten ﷺ: „Sagt lā ilāha illa llāh“ – ihre Antwort zitiert Vers 5.", quelle: "Sunan at-Tirmidhī, Nr. 3232; von den Hadith-Gelehrten als zuverlässig (hasan/sahih) eingestuft; Musnad Aḥmad, Nr. 2008"}
],
begriffe: [
 {arab: "أَوَّاب", tr: "awwāb", wurzel: "ʾ-w-b", erkl: "Intensivform von āba (zurückkehren): der immer wieder Umkehrende – das Leitwort der Sure (über Dāwūd, Sulaimān, Ayyūb; vgl. qalb munīb in Lektion 34). Nicht Fehlerlosigkeit adelt die Großen, sondern die Geschwindigkeit ihrer Rückkehr."},
 {arab: "الْخُلَطَاء", tr: "al-chulaṭāʾ", wurzel: "ch-l-ṭ", erkl: "„Die Teilhaber/Partner“ (38:24): „Viele Partner begehen gegeneinander Übergriffe – außer denen, die glauben und gute Werke tun, und das sind wenige.“ Dāwūds Lehrsatz über Geschäftspartnerschaften – realistisch und bis heute gültig."},
 {arab: "الصَّافِنَات الْجِيَاد", tr: "aṣ-ṣāfināt al-dschiyād", wurzel: "ṣ-f-n / dsch-w-d", erkl: "„Die edlen, (auf drei Beinen) stehenden Rennpferde“ Sulaimāns (38:31) – Inbegriff legitimer, schöner Machtmittel. Sein Satz dazu: „Ich habe die Liebe der Güter geliebt aufgrund des Gedenkens meines Herrn“ – bis sie ihn vom ʿAṣr-Dhikr ablenkten: Da trennte er sich von ihnen. Der Maßstab für jedes Hobby."},
 {arab: "رُخَاء", tr: "ruchāʾ", wurzel: "r-ch-w", erkl: "38:36: Allah machte Sulaimān „den Wind dienstbar, der auf seinen Befehl sanft (ruchāʾan) wehte, wohin er wollte“ – Antwort auf sein Gebet um eine einzigartige Herrschaft (38:35). Macht als Gabe NACH der Umkehr – die Reihenfolge ist die Lektion."},
 {arab: "اُرْكُضْ بِرِجْلِك", tr: "urkuḍ bi-ridschlik", wurzel: "r-k-ḍ", erkl: "„Tritt mit deinem Fuß auf!“ (38:42) – zu Ayyūb: Die Heilquelle entspringt unter seinem eigenen Fußtritt. Allahs Hilfe kommt oft durch einen kleinen eigenen Schritt – Wunder und Mitwirkung schließen sich nicht aus."},
 {arab: "ضِغْث", tr: "ḍiġth", wurzel: "ḍ-ġ-th", erkl: "„Ein Bündel (Halme)“ (38:44): Ayyūb hatte im Leid geschworen, seine Frau (die ihn nie verließ) zu schlagen; Allah löst den Schwur barmherzig: ein symbolisches Bündel, ein Schlag – Eid erfüllt, niemand verletzt. Die Scharia sucht Auswege der Milde (vgl. die Diskussion zu 4:34, Brennpunkte)."},
 {arab: "أَنَا خَيْرٌ مِّنْهُ", tr: "ana chairun minhu", wurzel: "ch-y-r", erkl: "„ICH bin besser als er“ (38:76) – der Satz des Iblīs, Urformel allen Hochmuts: Vergleich + Herkunftsstolz. Die Gelehrten: Jede Überheblichkeit gegenüber Menschen wiederholt dieses Argument in Varianten (Abstammung, Geld, Bildung, sogar Frömmigkeit)."}
],
tafsir: [
 {vers: "Verse 1–16", text: "Nach Schwur und Anlass-Szene diagnostiziert die Sure den wahren Grund der Ablehnung: „Nein! Sie sind (noch) in Stolz und Widerstreit (fī ʿizzatin wa-schiqāq)“ (38:2) – nicht in Beweisnot. Vers 8 legt den Neid offen („auf IHN unter uns?“), und Allah antwortet mit der Frage, die jeden Verteilungsneid erledigt: „Besitzen SIE etwa die Schatzkammern der Barmherzigkeit deines Herrn?“ (38:9) – Prophetie wird nicht im Stammesrat vergeben. Ibn Kathīr: Die Drohkulisse der Gegner („eine Schar der Verbündeten wird dort geschlagen“, 38:11) nimmt schon Badr vorweg – wie 54:45 (Lektion 37)."},
 {vers: "Verse 17–29: Dāwūd", text: "Erst das Porträt: der kraftvolle Anbeter (dhā l-aid – „Besitzer der Kraft“), mit dem die Berge und Vögel im Tasbīḥ einstimmen, dem Allah „die Weisheit und die entscheidende Rede (faṣl al-chiṭāb)“ gab. Dann die Prüfung: Zwei Streitende übersteigen die Mauer seines Gebetsraums – der eine klagt: „Dieser mein Bruder hat 99 Schafe, ich habe EIN Schaf, und er sagt: Vertrau es mir an – und überwand mich in der Rede.“ Dāwūd urteilt sofort für den Kläger – und begreift im selben Moment (die eigene Lage gespiegelt, bei aller Zurückhaltung der sahih Quellen über die Hintergründe): „Er meinte, Wir hätten ihn nur geprüft, und bat seinen Herrn um Vergebung, fiel in Verbeugung nieder und kehrte um (anāba).“ – „Da vergaben Wir ihm dies; für ihn ist bei Uns wahrlich Nähe und ein schönes Heimkommen.“ Lehren der Mufassirūn: (1) Nie nach EINER Partei urteilen – Dāwūds Fehler war das Urteil vor der Gegenrede. (2) Die Reaktion auf den erkannten Fehler macht den Rang: Istiġfār, Sadschda, Umkehr – binnen eines Verses. (3) 38:26 zieht das Amtsprinzip: „O Dāwūd, Wir haben dich zum Statthalter auf der Erde gemacht – so richte zwischen den Menschen mit der Wahrheit und folge nicht der Neigung (hawā).“ Der Vers hängt in jedem islamischen Gerichtssaal der Geschichte."},
 {vers: "Verse 30–40: Sulaimān", text: "Die Pferde-Episode: Die Vorführung der edlen Rosse zieht sich „bis sie (die Sonne) sich hinter dem Vorhang verbarg“ – Sulaimān erkennt, dass ihn das Liebste vom Gedenken ablenkte, lässt sie zurückbringen „und begann, über Beine und Hälse zu streichen“ (nach verbreiteter klassischer Deutung: Er gab sie hin/opferte sie; nach anderer: liebevolle Musterung – die Lektion bleibt: sofortige Korrektur der Prioritäten). Dann die zweite Prüfung: „Wir warfen auf seinen Thron einen Leib“ – und seine Reaktion ist wieder anāba (Umkehr) plus das berühmte Gebet: „Mein Herr, vergib mir und schenke mir eine Herrschaft, die keinem nach mir geziemt – Du bist der Freigebige.“ Erhört: dienstbarer Wind, arbeitende Dschinn-Scharen, „Das ist Unsere Gabe – so erweise Wohltaten oder halte zurück, ohne Abrechnung.“ Hierher gehört die Sunna-Szene: Ein Ifrīt wollte das Gebet des Propheten ﷺ stören; er packte ihn und wollte ihn an einen Pfeiler der Moschee binden – „doch ich erinnerte mich an das Wort meines Bruders Sulaimān: Mein Herr, schenke mir eine Herrschaft, die keinem nach mir geziemt – da ließ ich ihn beschämt los“ (Sahih al-Buchari, Nr. 461; Sahih Muslim, Nr. 541): gelebter Respekt vor dem Alleinstellungs-Gebet des Bruders."},
 {vers: "Verse 41–64: Ayyūb und die Reihe der Trefflichen", text: "Ayyūb ruft: „Mich hat der Satan mit Mühsal und Pein berührt“ – vollendeter Adab: Er schreibt das Übel nicht Allah zu und diktiert keine Lösung. Antwort: der Fußtritt zur Quelle, Heilung, die wiedergeschenkte Familie „und noch einmal so viele mit ihnen – als Barmherzigkeit von Uns und Ermahnung für die Verständigen“, und die ḍiġth-Lösung für seinen Schwur. Dann die Galerie: Ibrāhīm, Isḥāq, Yaʿqūb („Besitzer der Kraft und der Einsicht – Wir erwählten sie mit etwas Besonderem: dem Gedenken der (jenseitigen) Wohnstätte“), Ismāʿīl, al-Yasaʿ, Dhū l-Kifl – „alle gehören zu den Besten“. Gegenschnitt: die Höllen-Disputation der Verführer und Verführten („Kein Willkommen ihnen!“) und die Frage der Täter nach den Gläubigen, die sie im Diesseits verlachten: „Was ist mit uns, dass wir (hier) Männer nicht sehen, die wir zu den schlechten zählten?“ (38:62) – die Rangliste der Dunya gilt drüben nicht."},
 {vers: "Verse 65–88: Iblīs und das Siegel", text: "Die Ur-Szene: Erschaffung Ādams „mit Meinen beiden Händen“, der Befehl zur Niederwerfung, Iblīs' Weigerung aus Stolz („Ich bin besser als er“), Verfluchung, Fristgewährung – und sein Schwur: „Bei Deiner Macht, ich werde sie allesamt verführen – außer Deinen auserlesenen (aufrichtigen) Dienern (al-muchlaṣīn).“ As-Saʿdī: Iblīs selbst bezeugt, wo seine Macht endet – am Ichlāṣ (vgl. Lektion 22!). Der Schluss bündelt die Daʿwa des Propheten ﷺ in zwei Sätze, die du auswendig kennen solltest: „Sag: Ich verlange von euch dafür keinen Lohn, und ich gehöre nicht zu den Künstelnden (mutakallifīn). Es ist nur eine Ermahnung für die Welten. Und ihr werdet seine Kunde nach einer Weile (baʿda ḥīn) erfahren.“ – Echtheitskriterien jeder Verkündigung: kein Preisschild, keine Künstelei – und die Zeit als Zeuge."}
],
ahadith: [
 {text: "Die Delegation bei Abū Ṭālib und das Wort: „Sagt lā ilāha illa llāh – ein Wort, mit dem ihr die Araber beherrscht …“ – Anlass der Verse 1–8.", quelle: "Sunan at-Tirmidhī, Nr. 3232; Musnad Aḥmad, Nr. 2008; als zuverlässig eingestuft"},
 {text: "Ibn ʿAbbās: „Ṣād gehört nicht zu den (nachdrücklich) befohlenen Niederwerfungen – doch ich habe den Gesandten Allahs ﷺ darin niederfallen sehen.“ Und in einer Überlieferung: „Dāwūd warf sich in Reue nieder, und wir werfen uns in Dankbarkeit nieder.“", quelle: "Sahih al-Buchari, Nr. 1069 (vgl. 3422)"},
 {text: "Der Ifrīt im Gebet und das Gedenken an Sulaimāns Alleinstellungs-Gebet: „… da ließ ich ihn beschämt los.“", quelle: "Sahih al-Buchari, Nr. 461; Sahih Muslim, Nr. 541"},
 {text: "„Kein Prophet wurde härter geprüft …“ – „Die am härtesten geprüften Menschen sind die Propheten, dann die Nächstbesten …“ – der Rahmen für Ayyūbs Geschichte.", quelle: "Sunan at-Tirmidhī, Nr. 2398; sahih"}
],
hanafi: "38:24 (Dāwūds Niederwerfung) zählt nach hanafitischer Schule zu den 14 Pflicht-Sadschdas des Korans: sadschdat at-tilāwa ist hier wādschib – anders als bei den Schāfiʿiten, die die Sadschda in Ṣād als Dank-Niederwerfung (sadschdat schukr) außerhalb der 14 führen und sie im Gebet sogar auslassen. Der Buchari-Bericht oben zeigt beide Seiten: ‚nicht nachdrücklich befohlen – doch der Prophet ﷺ tat sie'. Für dich als Hanafi praktisch: Beim Lesen oder Hören von 38:24 die Tilāwa-Sadschda verrichten wie bei 96:19 (Lektion 1) und 53:62 (Lektion 23).",
umsetzung: [
 "Übernimm den awwāb-Standard: Miss dich nicht an der Fehlerfreiheit, sondern an der Rückkehr-Geschwindigkeit. Ziel diese Woche: Zwischen Fehler und Istiġfār sollen Minuten liegen, nicht Tage – Dāwūd brauchte einen Vers.",
 "Mach den Sulaimān-Test mit deinem liebsten Besitz/Hobby: Lenkt es dich von Gebet und Dhikr ab? Dann beschneide es sofort und sichtbar – nicht weil es harām wäre, sondern weil deine Prioritäten dir gehören sollen.",
 "Urteile nie nach einer Seite (38:24+26): In Streitfällen – Familie, Arbeit, Gemeinde – grundsätzlich beide anhören, bevor du auch nur innerlich urteilst; und prüfe dein Urteil auf hawā (Eigeninteresse).",
 "Lerne Ayyūbs Duʿā-Adab (38:41, vgl. 21:83): Not benennen, Allahs Barmherzigkeit anrufen, keine Lösung diktieren. Und bei Schwüren, die du bereust: Die Scharia kennt milde Auswege (Kaffāra) – frag nach, statt stur Schaden anzurichten.",
 "Sprich bei 38:24 die Tilāwa-Sadschda (hanafitisch wādschib) – damit hast du jetzt drei Sadschda-Verse im aktiven Bestand: 96:19, 53:62, 38:24."
]
},

// ───────────────────────── Lektion 39: Al-Aʿrāf ─────────────────────────
{
sure: 7, offb: 39, name: "Al-Aʿrāf", arab: "سُورَةُ الْأَعْرَافِ", de: "Die Höhen", verse: 206, ort: "Mekka",
zeit: "Mittel- bis spätmekkanisch – die längste mekkanische Sure: das Geschichtsbuch der Prophetenschaft",
kurz: "Die längste Sure Mekkas – und die erste, die die Menschheitsgeschichte als EINE durchgehende Erzählung aufspannt: vom Urbeginn (Iblīs gegen Ādam) über die große Prophetenkette (Nūḥ, Hūd, Ṣāliḥ, Lūṭ, Schuʿaib) bis zum ausführlichsten Mūsā-Bericht der bisherigen Offenbarung – und mündend im Ur-Bund aller Seelen: „Bin Ich nicht euer Herr? Sie sagten: Doch, wir bezeugen es“ (7:172). Dazwischen die Szenen des Jüngsten Tages, denen die Sure ihren Namen verdankt: die Leute der „Höhen“ (al-aʿrāf) zwischen Paradies und Hölle. Ihre Lebensregeln sind Klassiker: „Zieht euren Schmuck bei jeder Gebetsstätte an, esst und trinkt, aber seid nicht maßlos“ (7:31), „Meine Barmherzigkeit umfasst alles“ (7:156), „Nimm den leichten Weg, gebiete das Gute und wende dich von den Toren ab“ (7:199). Sie endet mit dem Hör-Gebot beim Koran (7:204) und der ersten Sadschda des Mushaf (7:206).",
schluessel: {arab: "أَلَسْتُ بِرَبِّكُمْ ۖ قَالُوا بَلَىٰ شَهِدْنَا", ueb: "„Bin Ich nicht euer Herr?“ Sie sagten: „Doch, wir bezeugen es.“", ref: "7:172"},
kontext: ["Diese Sure markiert eine neue Phase der Offenbarung: Nach den kurzen Weckruf-Suren kommt jetzt das große Format – Geschichte als Argument. Die Quraisch sollten sich in den Völkern wiedererkennen, die vor ihnen Gesandte ablehnten; die Muslime sollten aus denselben Geschichten Standfestigkeit ziehen. Jede Episode folgt dem Muster: Gesandter → Botschaft („Dient Allah, ihr habt keinen Gott außer Ihm“) → Ablehnung durch die satte Elite (al-malaʾ) → Rettung der Gläubigen, Untergang der Leugner.",
"Der Name kommt von 7:46–49: Zwischen Paradies und Hölle steht eine Scheidewand, auf deren Höhen (aʿrāf) Menschen stehen, „deren gute und schlechte Taten sich die Waage halten“ (so die verbreitete Deutung) – sie erkennen beide Seiten an ihren Merkmalen, grüßen die Paradiesleute voller Sehnsucht und flehen, nicht zu den Ungerechten gestellt zu werden; am Ende lässt Allah sie eintreten. Ein Bild der Hoffnung und der Warnung zugleich: Wer knapp lebt, lebt riskant.",
"Höhepunkt für dein Verständnis des Menschen ist 7:172, der Vers vom Ur-Bund (mīthāq): Allah nahm aus den Lenden der Kinder Ādams ihre Nachkommenschaft und ließ sie gegen sich selbst bezeugen: „Bin Ich nicht euer Herr?“ – „Doch!“ – „… damit ihr nicht am Tag der Auferstehung sagt: Wir wussten davon nichts.“ Deshalb heißt die Urausrichtung des Menschen fiṭra: Jeder trägt die Antwort „balā“ in sich; Daʿwa ist Erinnerung, nicht Neuinstallation. Der Prophet ﷺ: „Jedes Neugeborene wird auf der fiṭra geboren – seine Eltern machen es dann zum Juden, Christen oder Magier“ (Sahih al-Buchari, Nr. 1358; Sahih Muslim, Nr. 2658)."],
asbab: ["Für die Sure als Ganze ist kein Einzelanlass überliefert (mekkanische Grundsatzoffenbarung). Zu 7:31 („Zieht euren Schmuck bei jeder Gebetsstätte an“) berichtet Ibn ʿAbbās den Anlass: Araber der Dschāhiliyya umkreisten die Kaaba nackt – Männer bei Tag, Frauen bei Nacht –, weil sie meinten, in ‚Sündenkleidern' dürfe man nicht ṭawāf machen; dazu kam der Vers herab (Sahih Muslim, Nr. 3028)."],
begriffe: [
 {arab: "الْأَعْرَاف", tr: "al-aʿrāf", wurzel: "ʿ-r-f", erkl: "„Die Höhen“ – die erhöhten Stellen der Scheidewand zwischen Paradies und Hölle (von ʿurf: das Erhöhte; dieselbe Wurzel wie maʿrūf, das ‚anerkannte Gute'). Ihre Leute: nach der Hauptdeutung die, deren Waagschalen gleichstehen – das Bild aller, die ‚gerade so' leben."},
 {arab: "الْمَلَأ", tr: "al-malaʾ", wurzel: "m-l-ʾ", erkl: "„Die Vornehmen/Führungsschicht“ – das Stammwort jeder Prophetengeschichte dieser Sure: Immer ist es der malaʾ, der zuerst ablehnt (7:60, 66, 75, 88, 109). Etablierte Macht hat am meisten zu verlieren – darum hört sie am schlechtesten."},
 {arab: "لِبَاس التَّقْوَى", tr: "libās at-taqwā", wurzel: "l-b-s", erkl: "7:26: Allah sandte „Kleidung, die eure Blöße verbirgt, und Schmuck – doch die Kleidung der Gottesfurcht, die ist besser.“ Nach der Ādam-Geschichte (deren erste Folge der Sünde die Entblößung war): Das äußere Gewand bedeckt den Körper, Taqwā bedeckt die Seele. Beide gehören zusammen – gegen Nacktkult und gegen Schein-Frömmigkeit ohne Stoff."},
 {arab: "وَكُلُوا وَاشْرَبُوا وَلَا تُسْرِفُوا", tr: "wa-lā tusrifū", wurzel: "s-r-f", erkl: "7:31: „Esst und trinkt, aber seid nicht maßlos (lā tusrifū) – Er liebt nicht die Maßlosen.“ Die islamische Ernährungs- und Konsumregel in einem Halbvers: alles Gute erlaubt, die Grenze heißt isrāf. Die Ärzte der klassischen Zeit nannten diesen Vers die Summe der Medizin."},
 {arab: "الْمِيثَاق / الْفِطْرَة", tr: "mīthāq / fiṭra", wurzel: "w-th-q / f-ṭ-r", erkl: "Der Ur-Bund von 7:172 und die daraus folgende Urausrichtung: Jede Seele hat Allah bereits als Herrn bezeugt. Kufr ist deshalb im Koran ‚Vergessen' und ‚Zudecken' (kafara!), Daʿwa ist ‚Erinnern' (dhikrā) – das ändert den ganzen Ton deiner Gespräche."},
 {arab: "الْأَسْمَاء الْحُسْنَى", tr: "al-asmāʾ al-ḥusnā", wurzel: "s-m-w / ḥ-s-n", erkl: "7:180: „Allah gehören die schönsten Namen – so ruft Ihn damit an, und lasst die, die Seine Namen verdrehen.“ Grundvers der Namen-Lehre; dazu der Hadith: „Allah hat 99 Namen – wer sie erfasst (aḥṣāhā), geht ins Paradies“ (Sahih al-Buchari, Nr. 2736; Sahih Muslim, Nr. 2677): erfassen = kennen, verstehen, danach leben."},
 {arab: "خُذِ الْعَفْو", tr: "chudhi l-ʿafw", wurzel: "ʿ-f-w", erkl: "7:199: „Nimm den leichten Weg (das, was die Menschen leicht geben können), gebiete das Gute (ʿurf) und wende dich von den Unwissenden ab.“ – Die Daʿwa- und Alltags-Charta in drei Befehlen; ʿAbdullāh ibn az-Zubair: „Der Vers wurde über die Charaktere der Menschen herabgesandt – nimm sie, wie sie geben können“ (Sahih al-Buchari, Nr. 4644)."}
],
tafsir: [
 {vers: "Verse 1–58: Ādam, Iblīs und die Grundausstattung", text: "Die Sure eröffnet mit ihrem Programm („ein Buch, zu dir herabgesandt – damit du mit ihm warnst“) und erzählt dann den Ur-Konflikt ausführlicher als Ṣād: Iblīs' Hochmut, sein Antrag auf Frist und seine Strategie-Erklärung: „Ich werde ihnen gewiss auf Deinem geraden Weg auflauern, dann von vorn und hinten, rechts und links über sie kommen – und Du wirst die meisten nicht dankbar finden“ (7:16–17): der älteste Lagebericht über Zweifel, Dunya-Gier, Jenseits-Vergessen und Schirk (so deuteten die Frühgelehrten die vier Richtungen). Ādams Fall durch das Einflüstern („Euer Herr hat euch den Baum nur verboten, damit ihr nicht Engel werdet…“ – die Lüge arbeitet IMMER mit ‚Gott gönnt dir nichts') und der Unterschied zur Iblīs-Sünde: Ādam bereut mit dem Gebet, das jeder kennen sollte: „Unser Herr, wir haben uns selbst Unrecht getan – wenn Du uns nicht vergibst und Dich unser erbarmst, gehören wir gewiss zu den Verlierern“ (7:23). Hochmut rechtfertigt, Demut bereut – daran scheiden sich Iblīs und Ādam, nicht an der Fehlerlosigkeit. Dann die Menschheits-Anreden („O Kinder Ādams“, viermal): Kleidung und libās at-taqwā, Schmuck bei der Gebetsstätte, essen-trinken-nicht-maßlos, und die Regel „Wer hat den Schmuck Allahs verboten, den Er für Seine Diener hervorgebracht hat?“ (7:32) – gegen jede selbsterfundene Verbotsreligion."},
 {vers: "Verse 59–102: die Prophetenkette", text: "Fünf Stationen im Schnelldurchgang, jede mit eigener Krankheit: Nūḥs Volk – Götzentreue der Tradition; ʿĀd (Hūd) – Kraftprotzerei („Wer ist stärker als wir?“); Ṯamūd (Ṣāliḥ) – Technik-Stolz und das Kamel-Verbrechen; Lūṭs Volk – die neue Schamlosigkeit („Ihr begeht das Schändliche, worin euch keiner der Weltenbewohner zuvorkam“); Madyan (Schuʿaib) – Wirtschaftskriminalität („Gebt volles Maß und Gewicht und schmälert den Menschen nicht ihre Sachen“ – vgl. Lektion zu 83 künftig). Al-Qurṭubī: Die Sure zeigt, dass jede Zivilisation ihre Spezialsünde hat – und ALLE dieselbe Wurzel: die Ablehnung der Korrektur. Dazwischen der Gnaden-Grundsatz als Scharnier (7:94–96): Allah prüft erst mit Härte (zur Demut), dann mit Wohlstand (zur Dankbarkeit) – „und hätten die Bewohner der Städte geglaubt und Taqwā gehabt, hätten Wir ihnen Segnungen von Himmel und Erde geöffnet.“"},
 {vers: "Verse 103–162: Mūsā", text: "Der erste große Mūsā-Bericht der Offenbarungsfolge: Stab und weiße Hand vor Pharao, das Zauberer-Duell („Sie warfen – und bezauberten die Augen der Menschen“; die Zauberer selbst fallen als Erste in Sadschda: „Wir glauben an den Herrn der Welten!“ – und trotzen Pharaos Kreuzigungsdrohung: Experten erkennen Echtes), die Plagen (Flut, Heuschrecken, Läuse, Frösche, Blut) mit dem immer gleichen Wortbruch Pharaos, der Durchzug durchs Meer – und dann die zweite Hälfte, die kaum jemand kennt: Israel NACH der Rettung. Kaum gerettet, verlangen sie: „Mach uns einen Gott, wie sie Götter haben“ (7:138); das Kalb in Mūsās Abwesenheit; seine Rückkehr mit den Tafeln, „in deren Niederschrift Rechtleitung und Barmherzigkeit sind“. Hier steht der große Barmherzigkeits-Vers 7:156: „Meine Strafe trifft, wen Ich will – doch Meine Barmherzigkeit umfasst alles (wasiʿat kulla schaiʾ)“, verbunden mit der Beschreibung des kommenden Propheten ﷺ bei den Schriftbesitzern: „der Gesandte, der schriftunkundige Prophet, den sie bei sich in Tora und Evangelium verzeichnet finden – der ihnen das Gute gebietet, das Verwerfliche verbietet, die guten Dinge erlaubt, die schlechten verwehrt und ihnen ihre Last und die Fesseln abnimmt“ (7:157) – das Selbstporträt des Islam als Religion der Entlastung."},
 {vers: "Verse 163–206: Sabbatbrecher, Ur-Bund und Schlussregeln", text: "Die Sabbatbrecher-Episode (die Fische, die nur am Sabbat kamen; die Stadt, die sich zu Tode tricksen wollte; gerettet werden allein „diejenigen, die das Böse verboten“ – 7:165: die dritte Gruppe, die schwieg, wird übergangen: Schweigen ist keine Rettungsposition, vgl. Lektion 26). Dann der Mann, dem Allah Seine Zeichen gab „und der sich davon löste … wie der Hund: hechelt, ob du ihn anjagst oder in Ruhe lässt“ (7:175–176) – Wissen ohne Taqwā als schlimmste Besitzform. Darauf der Ur-Bund (7:172) und die fiṭra-Lehre. Die Schlussverse sind dein Praxis-Paket: die schönsten Namen (180), die Waswasa-Regel „Wenn dich vom Satan eine Anwandlung trifft, such Zuflucht bei Allah“ mitsamt der Beobachtung, dass die Muttaqīn dann „sehend werden“ (200–201, vgl. Lektion 21), die Daʿwa-Charta chudhi l-ʿafw (199), das Hör-Gebot: „Wenn der Koran vorgetragen wird, hört zu und schweigt, auf dass ihr Erbarmen findet“ (204) – und der stille Dhikr „in deiner Seele, in Demut und Furcht, ohne laute Worte, morgens und abends“ (205). Vers 206 ist die erste Tilāwa-Sadschda des Mushaf: Die Engel „preisen Ihn und werfen sich vor Ihm nieder“ – und der Leser mit ihnen."}
],
ahadith: [
 {text: "„Jedes Neugeborene wird auf der fiṭra geboren; seine Eltern machen es dann zum Juden, Christen oder Magier …“ – der Sunna-Kommentar zu 7:172.", quelle: "Sahih al-Buchari, Nr. 1358; Sahih Muslim, Nr. 2658"},
 {text: "„Allah hat neunundneunzig Namen, hundert weniger einen; wer sie erfasst, tritt ins Paradies ein.“ – zu 7:180.", quelle: "Sahih al-Buchari, Nr. 2736; Sahih Muslim, Nr. 2677"},
 {text: "Ibn ʿAbbās über den nackten Ṭawāf der Dschāhiliyya als Anlass von 7:31.", quelle: "Sahih Muslim, Nr. 3028"},
 {text: "„Der Sohn Ādams füllt kein Gefäß, das schlimmer wäre als sein Bauch. Dem Sohn Ādams genügen (wenige) Bissen, die seinen Rücken aufrecht halten; wenn es denn sein muss: ein Drittel für sein Essen, ein Drittel für sein Trinken, ein Drittel für seinen Atem.“ – die Sunna zu 7:31.", quelle: "Sunan at-Tirmidhī, Nr. 2380; sahih"}
],
hanafi: "Zwei hanafitische Anker in dieser Sure: (1) 7:204 („Wenn der Koran vorgetragen wird, hört zu und schweigt“) ist – zusammen mit dem Hadith „Die Rezitation des Imams ist Rezitation für den hinter ihm“ (Ibn Mādscha, Nr. 850) – der Hauptbeleg der Schule dafür, dass der Betende hinter dem Imam NICHT rezitiert, auch nicht die Fātiḥa (vgl. Lektion 5). (2) 7:206 ist die erste der 14 Tilāwa-Sadschdas: hanafitisch wādschib bei Rezitation und beim Hören. Zusatz: Aus 7:31 („euren Schmuck bei jeder Gebetsstätte“) leiten die Fuqahāʾ die Empfehlung ab, zum Gebet – besonders Freitag und Fest – gepflegte Kleidung zu tragen: Wer vor den König tritt, kleidet sich entsprechend.",
umsetzung: [
 "Lerne Ādams Duʿā (7:23) auswendig – rabbana ẓalamnā anfusanā … – und mache sie zu deiner Standard-Tauba-Formel: Sie trennt dich im Fehlerfall von der Iblīs-Logik des Rechtfertigens.",
 "Iss nach 7:31 + Tirmidhī 2380: eine Woche lang bewusst die Drittel-Regel – du wirst merken, wie viel isrāf Gewohnheit war. (Essen ist Tazkiya-Trainingsfeld Nummer eins.)",
 "Begegne Menschen als fiṭra-Träger (7:172): Im Daʿwa-Gespräch nicht ‚beweisen', sondern ERINNERN – Fragen stellen, die das innere balā wecken („Wer hat dich versorgt, als du nichts konntest?“).",
 "Wende die chudhi-l-ʿafw-Charta (7:199) in deiner schwierigsten Beziehung an: das Leichte nehmen, das Gute gebieten, vom Provozierenden abwenden – drei Befehle, ein Monat Übung.",
 "Vervollständige deine Sadschda-Liste: 7:206 ist die erste des Mushaf (hanafitisch wādschib) – du kennst jetzt vier: 7:206, 38:24, 53:62, 96:19."
]
},

// ───────────────────────── Lektion 40: Al-Ǧinn ─────────────────────────
{
sure: 72, offb: 40, name: "Al-Ǧinn", arab: "سُورَةُ الْجِنِّ", de: "Die Ǧinn", verse: 28, ort: "Mekka",
zeit: "Spätmekkanisch – nach der Rückkehr des Propheten ﷺ aus Ṭāʾif, als eine Schar Ǧinn seiner Rezitation lauschte",
kurz: "Die Sure vom unsichtbaren Publikum: Während die Menschen Mekkas den Koran ablehnten und Ṭāʾif den Propheten ﷺ mit Steinen vertrieb, hörte eine Schar Ǧinn seine Rezitation – und ihre Reaktion beschämt die Menschen: „Wir haben einen wunderbaren Koran gehört, der zur Besonnenheit leitet; so glauben wir an ihn, und wir werden unserem Herrn niemanden beigesellen.“ Die Sure gibt ihr Bekenntnis in direkter Rede wieder: ihre Selbstkorrektur über Allah („Erhaben ist die Größe unseres Herrn – Er hat sich weder Gefährtin noch Kind genommen“), ihre Ehrlichkeit über die eigenen Reihen („Unter uns sind Rechtschaffene und solche, die es nicht sind“), das Ende ihres Himmels-Lauschens („Wir fanden ihn mit strengen Wächtern und Feuerpfeilen gefüllt“) und ihr Fazit: „Die Gebetsstätten gehören Allah – so ruft neben Allah niemanden an.“ Dazu die Grenzen des Gesandten ﷺ: Er besitzt weder Schaden noch Nutzen für euch (72:21) – und das Verborgene kennt nur Allah, der davon allein Seinen Gesandten zeigt, was Er will (72:26–27).",
schluessel: {arab: "وَأَنَّ الْمَسَاجِدَ لِلَّهِ فَلَا تَدْعُوا مَعَ اللَّهِ أَحَدًا", ueb: "Und die Gebetsstätten gehören Allah; so ruft neben Allah niemanden an.", ref: "72:18"},
kontext: ["Ibn ʿAbbās berichtet den Hintergrund: Der Prophet ﷺ war mit einigen Gefährten unterwegs zum Markt ʿUkāẓ. Den Satanen war inzwischen der Zugang zu den Himmelsnachrichten versperrt – Feuerpfeile trafen die Lauscher. Auf der Suche nach der Ursache durchstreiften sie die Erde, und eine Gruppe kam nach Nachla, wo der Prophet ﷺ mit seinen Gefährten das Fadschr-Gebet verrichtete. „Als sie den Koran hörten, lauschten sie ihm und sagten: DAS ist es, was sich zwischen uns und die Himmelsnachricht gestellt hat!“ Sie kehrten zu ihrem Volk zurück: „Wir haben einen wunderbaren Koran gehört …“ – und Allah offenbarte Seinem Propheten: „Sag: Mir ist offenbart worden, dass eine Schar der Ǧinn zuhörte …“ (Sahih al-Buchari, Nr. 773; Sahih Muslim, Nr. 449).",
"Zeitlich fällt das in die bitterste Phase: Nach dem Tod Abū Ṭālibs und Chadīdschas hatte Ṭāʾif den Propheten ﷺ blutig abgewiesen. Die Sure antwortet auf die Verwerfung durch Menschen mit der Annahme durch eine ganz andere Schöpfung – Allahs Botschaft findet ihre Hörer, notfalls jenseits der Sichtbarkeit. (In einer späteren Begegnung rezitierte der Prophet ﷺ den Ǧinn Sure ar-Raḥmān – sie antworteten auf jedes „Welche der Wohltaten…“ demütiger als die Menschen; at-Tirmidhī, Nr. 3291.)",
"Die ʿAqīda-Erträge der Sure sind für heute hochaktuell: (1) Ǧinn existieren, sind verantwortliche Geschöpfe mit Gläubigen und Ungläubigen – weder Märchen noch Allmächte. (2) Wahrsagerei ist tot: Der Lauschkanal ist versperrt (72:8–9); wer Zukunftswissen verkauft, betrügt (vgl. den Wahrsager-Hadith in Lektion 20). (3) Menschen, die bei Ǧinn Zuflucht suchten, „mehrten sie nur an Bedrängnis“ (72:6) – jede ‚Geister-Kooperation' stärkt die falsche Seite. (4) Selbst der Gesandte ﷺ verfügt nicht über Schaden und Nutzen – wie viel weniger ‚Heiler' und ‚Schejchs' mit Ǧinn-Kontakten."],
asbab: [
 {text: "Ibn ʿAbbās: die Ǧinn von Nachla hören das Fadschr-Gebet des Propheten ﷺ auf dem Weg nach ʿUkāẓ – Anlass der Herabsendung.", quelle: "Sahih al-Buchari, Nr. 773; Sahih Muslim, Nr. 449"}
],
begriffe: [
 {arab: "نَفَر مِّنَ الْجِنّ", tr: "nafar mina l-dschinn", wurzel: "dsch-n-n", erkl: "„Eine Schar der Ǧinn“ (3–10 Personen). Zur Wurzel ‚verborgen sein' vgl. Lektion 2 (madschnūn). Ǧinn: aus rauchlosem Feuer erschaffene (55:15), verantwortliche Wesen mit Ehe, Tod und Gericht – Adressaten derselben Offenbarung (vgl. 51:56)."},
 {arab: "قُرْآنًا عَجَبًا", tr: "qurʾānan ʿadschabā", wurzel: "ʿ-dsch-b", erkl: "„Einen wunderbaren/erstaunlichen Koran“ – das Urteil der unvoreingenommenen Erst-Hörer: Staunen. Sie hatten keine Stammesinteressen, keinen Status zu verlieren – und hörten deshalb, WAS gesagt wurde, nicht WER es sagte."},
 {arab: "الرُّشْد", tr: "ar-ruschd", wurzel: "r-sch-d", erkl: "„Besonnenheit/der rechte Weg“ (72:2): „er leitet zum ruschd“ – dieselbe Wurzel wie raschīd und das Gegenwort zu ġayy (Verirrung, vgl. 2:256: „der ruschd ist klar geworden vom ġayy“). Rechtleitung als Reife, nicht als Dressur."},
 {arab: "شِهَاب رَّصَد", tr: "schihāb raṣad", wurzel: "sch-h-b / r-ṣ-d", erkl: "„Lauernde Feuerpfeile“ (72:9) – die Geschosse gegen lauschende Satane (vgl. 67:5; 37:10). Mit der Sendung des Propheten ﷺ wurde der Himmel ‚verriegelt': das endgültige Aus jeder Wahrsagerei – nur gestohlene Wortfetzen mit hundert Lügen erreichten die Kähin früher (Sahih al-Buchari, Nr. 3210)."},
 {arab: "الْقَاسِطُون", tr: "al-qāsiṭūn", wurzel: "q-s-ṭ", erkl: "72:14–15: „Unter uns sind die Gottergebenen und unter uns die qāsiṭūn (Abweichler/Ungerechten) … die sind Brennholz der Hölle.“ Feine Sprache: qāsiṭ = der vom Recht Abweichende, muqsiṭ = der Gerechte – eine Wurzel, zwei Richtungen. Auch die Ǧinn-Welt ist plural: Es gibt muslimische Ǧinn."},
 {arab: "لِبَدًا", tr: "libadā", wurzel: "l-b-d", erkl: "72:19: Als der ‚Diener Allahs' (der Prophet ﷺ) aufstand, Ihn anzurufen, „hätten sie ihn (vor Andrang) fast erdrückt“ (kānū ʿalaihi libadā – dicht gedrängt wie Filz; dieselbe Wurzel wie lubadā in Lektion 35). Deutungen: der Andrang der staunenden Ǧinn – oder der Menschen gegen ihn; beides zeigt: Dieses Gebet ließ niemanden kalt."},
 {arab: "عَالِم الْغَيْب", tr: "ʿālim al-ġaib", wurzel: "ġ-y-b", erkl: "72:26–27: „(Er ist) der Kenner des Verborgenen – Er gibt Sein Verborgenes niemandem preis, außer einem Gesandten, den Er erwählt hat …“ Die Verfassungsnorm des Ġaib: Zukunft, Herzen, Stunde – nur bei Allah; Propheten wissen davon exakt das Mitgeteilte (Wunder/Offenbarung), sonst niemand. Prüfstein gegen jeden ‚Wissenden'."}
],
tafsir: [
 {vers: "Verse 1–15: das Bekenntnis der Ǧinn", text: "Zwölf „dass“-Sätze geben ihr Gespräch wieder – ein Lehrstück in Umkehr: Staunen über den Koran, sofortiger Tauhīd („wir gesellen unserem Herrn niemanden bei“), Korrektur der eigenen Theologie („Erhaben ist die Größe unseres Herrn: Er hat sich weder Gefährtin noch Kind genommen – und der Tor unter uns pflegte über Allah Abwegiges zu sagen; wir aber meinten, Menschen und Ǧinn würden über Allah niemals Lügen sprechen“ – 72:3–5: Sie hatten Autoritäten blind geglaubt, weil ‚so viele nicht lügen können' – das Ende jedes Autoritäts-Arguments). Dann die Abrechnung mit dem Geschäftsmodell: Menschen suchten Schutz bei Ǧinn „und mehrten sie nur an Bedrängnis“ (6); der Himmel ist versperrt (8–9); und die Demut der Neubekehrten: „Wir wissen nicht, ob für die auf der Erde Schlechtes gewollt wird oder ob ihr Herr sie zum ruschd leiten will“ (10) – wer glaubt, hört auf, über Allahs Pläne zu spekulieren. Ihre Selbstauskunft 11 und 14 („unter uns Rechtschaffene und andere; wir waren Wege gespaltener Richtungen“) zeigt: Bekenntnis macht ehrlich, auch über die eigene Gruppe. Ibn Kathīr: Beachte den Missionsreflex – sie hörten, glaubten, „kehrten als Warner zu ihrem Volk zurück“ (46:29–31 erzählt dieselbe Szene): Iman, der nicht weitergibt, ist bei den Ǧinn gar nicht erst vorgesehen."},
 {vers: "Verse 16–24: Istiqāma, Moscheen und die Grenzen des Gesandten", text: "„Und wenn sie auf dem Weg geradeaus gingen (istaqāmū), würden Wir sie mit reichlichem Wasser tränken, um sie darin zu prüfen“ – Segen folgt der Istiqāma, und Segen ist selbst Prüfung (vgl. 7:96, Lektion 39). „Wer sich vom Gedenken seines Herrn abwendet, den steckt Er in ansteigende Strafe.“ Dann der Vers der Moscheen (18): al-masādschid – die Gebetsstätten (und nach Deutungen: die Körperglieder der Niederwerfung) gehören Allah ALLEIN: kein Anrufen von Heiligen, Gräbern, ‚Vermittlern' neben Ihm – gerade an heiligen Orten nicht. Die Verse 21–23 sind die Berufsbeschreibung des Propheten ﷺ in Reinform: „Sag: Ich vermag euch weder Schaden noch ruschd (zu bringen) … Mir obliegt nur die Übermittlung von Allah und Seine Botschaften.“ As-Saʿdī: Wenn schon der Gesandte ﷺ nur Übermittler ist – wie abwegig ist jede Daʿwa, die sich selbst zur Heilsinstanz macht, und jedes Bitten bei Verstorbenen um das, was nur Allah gibt."},
 {vers: "Verse 25–28: das Ġaib-Siegel", text: "„Sag: Ich weiß nicht, ob das, was euch versprochen wird, nahe ist oder ob mein Herr ihm eine Frist setzt – (Er ist) der Kenner des Verborgenen …“ Die Ausnahme: „außer einem Gesandten, mit dem Er zufrieden ist – dann lässt Er vor ihm und hinter ihm Wächter einherschreiten, damit Er weiß, dass sie die Botschaften ihres Herrn übermittelt haben.“ – Al-Qurṭubī: Sogar das offenbarte Ġaib wird von Engel-Eskorten gesichert (Schutz der Offenbarung auf dem Transportweg!). Das Siegel für deine Gespräche: Jeder Kartenleger, jedes Horoskop, jeder ‚Ǧinn-Sheikh' scheitert an 72:26–27 – und an der Rechnung des Propheten ﷺ: „Wer einen ʿarrāf (Wahrsager) aufsucht und ihn nach etwas fragt, dem wird vierzig Nächte kein Gebet angenommen“ (Sahih Muslim, Nr. 2230)."}
],
ahadith: [
 {text: "Ibn ʿAbbās: der Bericht von Nachla – die Ǧinn hören das Fadschr-Gebet, finden die Ursache der Himmelssperre und kehren als Gläubige zurück.", quelle: "Sahih al-Buchari, Nr. 773; Sahih Muslim, Nr. 449"},
 {text: "„Wer einen Wahrsager aufsucht und ihn nach etwas fragt, dem wird vierzig Nächte lang kein Gebet angenommen.“ – und wer ihm GLAUBT, „hat den Unglauben begangen gegenüber dem, was auf Muhammad herabgesandt wurde“ (Abū Dāwūd, Nr. 3904).", quelle: "Sahih Muslim, Nr. 2230; Sunan Abū Dāwūd, Nr. 3904 (sahih)"},
 {text: "Der Prophet ﷺ rezitierte den Ǧinn Sure ar-Raḥmān; sie antworteten auf jeden Refrain: „Nichts von Deinen Wohltaten, unser Herr, leugnen wir – Dir gebührt der Lobpreis“ – „die Ǧinn waren besser im Antworten als ihr“, sagte er den Gefährten.", quelle: "Sunan at-Tirmidhī, Nr. 3291; von al-Albānī als gut (hasan/sahih) eingestuft"},
 {text: "Zur Himmelssperre: Die Engel geben das Dekret weiter, der lauschende Satan schnappt ein Wort auf und wirft es dem Wahrsager zu, „und sie mischen hundert Lügen dazu“.", quelle: "Sahih al-Buchari, Nr. 3210 (vgl. 4800)"}
],
hanafi: "Aus 72:18 („Die Gebetsstätten gehören Allah – ruft neben Allah niemanden an“) ziehen die Gelehrten – hanafitische Fuqahāʾ eingeschlossen – die Linie für den Umgang mit Moscheen und Gräbern: Moscheen sind für reinen Gottesdienst; das Anrufen Verstorbener um Hilfe (istiġātha bi-l-amwāt) ist unzulässig – der Besuch von Gräbern zur Erinnerung und zum Duʿā FÜR die Toten ist Sunna, das Bitten AN die Toten verkehrt die Richtung. Ebenso klar ist die hanafitische Fatwa-Lage gegen Wahrsagerei und ‚Ǧinn-Dienstleister' (vgl. Lektion 20): Kein Muslim lässt sich Zukunft, Ehe- oder Krankheitsursachen von Ġaib-Anbietern deuten – Diagnose beim Arzt, Ruqya mit Koran, Tawakkul bei Allah.",
umsetzung: [
 "Höre den Koran einmal wie die Ǧinn von Nachla: ohne Vorwissen-Filter, als hörtest du ihn zum ersten Mal – z. B. eine Sure in bester Rezitation mit Übersetzung, volle Aufmerksamkeit. Ihr ‚qurʾānan ʿadschabā' ist reproduzierbar.",
 "Prüfe Autoritäts-Glauben (72:5): Wo übernimmst du religiöse ‚Fakten', nur weil ‚alle es sagen' oder ein Kanal es behauptet? Die Ǧinn wurden von dieser Haltung geheilt – Quellen prüfen ist Sunna dieser Sure.",
 "Null-Toleranz beim Ġaib-Markt: Horoskope, Kartenleger, ‚geistige Heiler', Ǧinn-Austreiber mit Geheimwissen – 72:26–27 + Muslim 2230 sind deine klare Antwort, auch in der Familie.",
 "Ehre 72:18 praktisch: In der Moschee nur Er – und nimm dir die Fadschr-Szene von Nachla als Ansporn, das Fadschr-Gebet in Gemeinschaft aufzuwerten: Es war DIESES Gebet, das die unsichtbare Welt bewegte."
]
},

// ───────────────────────── Lektion 41: Yā-Sīn ─────────────────────────
{
sure: 36, offb: 41, name: "Yā-Sīn", arab: "سُورَةُ يسٓ", de: "Yā-Sīn", verse: 83, ort: "Mekka",
zeit: "Mittelmekkanisch – die Sure der Sendungs-Gewissheit: ein Gesandter, eine Stadt, und die Zeichen in Erde und Himmel",
kurz: "Eine der meistgeliebten Suren des Islam. Sie beginnt mit einem Schwur auf die Sendung: „Yā-Sīn. Beim weisen Koran: Du gehörst wahrlich zu den Gesandten, auf einem geraden Weg.“ Ihr Herzstück ist die Geschichte der Stadt, zu der drei Gesandte kamen – und des Mannes „vom äußersten Ende der Stadt“, der herbeieilte, sein Volk verteidigend warnte, getötet wurde und noch im Paradies an sein Volk denkt: „O wüsste doch mein Volk, dass mein Herr mir vergeben und mich zu den Geehrten gestellt hat!“ Dann öffnet die Sure das Buch der Zeichen: die tote Erde, die lebendig wird, Nacht und Tag, Sonne und Mond – „alle schwimmen in einer Umlaufbahn“ –, das beladene Schiff. Und sie beantwortet die Knochen-Frage des Spötters mit dem vielleicht dichtesten Schöpfungsargument des Korans: „Sag: Lebendig macht sie Der, Der sie das erste Mal entstehen ließ.“ Ihr Schlusswort gehört zur Grundausstattung jedes Muslims: „Sein Befehl, wenn Er etwas will, ist nur, dass Er dazu sagt: Sei!, und es ist.“",
schluessel: {arab: "إِنَّمَا أَمْرُهُ إِذَا أَرَادَ شَيْئًا أَن يَقُولَ لَهُ كُن فَيَكُونُ", ueb: "Sein Befehl, wenn Er etwas will, ist nur, dass Er dazu sagt: Sei!, und es ist.", ref: "36:82"},
kontext: ["Zum Rang der Sure kursiert der berühmte Satz „Yā-Sīn ist das Herz des Korans“ – sei ehrlich damit: Der Hadith (at-Tirmidhī, Nr. 2887) ist nach dem Urteil der Hadith-Kritiker schwach (ḍaʿīf), ebenso die Umlauf-Hadithe über das Lesen bei Sterbenden („Lest Yā-Sīn über euren Toten“, Abū Dāwūd, Nr. 3121 – von vielen als schwach eingestuft, von manchen Gelehrten dennoch praktiziert). Die LIEBE zur Sure braucht diese schwachen Stützen gar nicht: Ihr Inhalt – Sendung, Zeichen, Auferstehung in 83 kompakten Versen – erklärt ihre Stellung von selbst.",
"Der Anlassbericht zum Schluss der Sure ist dagegen fest in der Tafsir-Literatur verankert: Ubayy ibn Chalaf (oder al-ʿĀṣ ibn Wāʾil) kam mit einem morschen Knochen zum Propheten ﷺ, zerrieb ihn vor seinen Augen und blies den Staub in den Wind: „Behauptest du, dass dein Herr DIESEN wieder lebendig macht?“ – Antwort des Himmels: „Er stellt Uns ein Gleichnis hin und vergisst seine eigene Erschaffung. Er sagt: Wer macht die Knochen lebendig, wenn sie zerfallen sind? Sag: Lebendig macht sie Der, Der sie das erste Mal entstehen ließ – Er weiß über jede Schöpfung Bescheid“ (36:77–79; Bericht u. a. bei al-Ḥākim, al-Mustadrak, von ihm als sahih eingestuft; Standardbericht bei Ibn Kathīr). Ubayy fiel später bei Uḥud – durch die Hand des Propheten ﷺ.",
"Die Stadt-Erzählung (36:13–29) lasen viele Mufassirūn als Antiochia; gesichert ist das nicht – und bewusst lässt der Koran Namen und Zeit offen: Es ist die Modell-Geschichte jeder Daʿwa: Gesandte kommen, die Mehrheit droht („Wir sehen in euch ein böses Vorzeichen – hört ihr nicht auf, steinigen wir euch“), ein Einzelner aus der Peripherie – kein Amt, kein Rang – rennt herbei und hält die beste Laien-Chuṭba des Korans: „Folgt denen, die keinen Lohn verlangen und rechtgeleitet sind! Und warum sollte ich Dem nicht dienen, Der mich erschaffen hat …?“"],
asbab: [
 {text: "Verse 77–83: der Mann mit dem morschen Knochen („Wer macht die Knochen lebendig, wenn sie zerfallen sind?“) – nach den Berichten Ubayy ibn Chalaf bzw. al-ʿĀṣ ibn Wāʾil.", quelle: "al-Ḥākim, al-Mustadrak (sahih nach seiner Einstufung); Tafsir Ibn Kathīr zu 36:77; al-Wāḥidī, Asbāb an-Nuzūl"}
],
begriffe: [
 {arab: "يسٓ", tr: "Yā-Sīn", wurzel: "–", erkl: "Zwei der geheimnisvollen Einzelbuchstaben (vgl. Lektion 2 zu ‚Nūn'). Die verbreitete Volksdeutung ‚O Mensch!' oder als Name des Propheten ﷺ ist sprachlich möglich, aber nicht gesichert – die ehrlichste Antwort bleibt: Allah weiß am besten; die Buchstaben selbst sind Teil der Herausforderung des unnachahmlichen Korans."},
 {arab: "أَقْصَى الْمَدِينَة", tr: "aqṣā l-madīna", wurzel: "q-ṣ-w", erkl: "„Das äußerste Ende der Stadt“ (36:20) – von dort „kam ein Mann gelaufen (yasʿā)“. Die Peripherie glaubt, das Zentrum spottet: ein Muster des Korans (vgl. 28:20, derselbe Ausdruck). Wahrheit braucht keinen Rang – sie braucht Beine."},
 {arab: "طَائِرُكُم مَّعَكُم", tr: "ṭāʾirukum maʿakum", wurzel: "ṭ-y-r", erkl: "36:19: Auf das ‚böse Omen' der Städter antworten die Gesandten: „Euer Vogel(omen) ist bei euch selbst“ – euer Unheil liegt in eurem eigenen Tun, nicht in unserer Botschaft. Die koranische Absage an Aberglauben und Sündenbock-Logik in vier Worten."},
 {arab: "سَلَام قَوْلًا", tr: "salāmun qaulan", wurzel: "s-l-m", erkl: "36:58: „Friede! – als (An)wort von einem barmherzigen Herrn.“ Der Gruß Allahs an die Paradiesleute, von vielen als Höhepunkt der Sure empfunden: Das letzte Wort der Reise ist Sein persönlicher Salām."},
 {arab: "فِي فَلَكٍ يَسْبَحُون", tr: "fī falakin yasbaḥūn", wurzel: "f-l-k / s-b-ḥ", erkl: "36:40: Sonne, Mond (und Gestirne) – „alle schwimmen in einer Umlaufbahn“. Sabaḥa: schwimmen/gleiten – Himmelskörper als Schwimmer auf Bahnen: „Weder ziemt es der Sonne, den Mond einzuholen, noch kommt die Nacht dem Tag zuvor“ – ein Ordnungs-Vers, den die Astronomie nur immer schöner gemacht hat."},
 {arab: "رَمِيم", tr: "ramīm", wurzel: "r-m-m", erkl: "„Morsch zerfallen“ (36:78) – der zerriebene Knochen des Spötters. Die Antwort argumentiert dreifach: Erst-Erschaffung (79), das Feuer aus dem grünen Baum (80 – Energie aus Biomasse: wer Feuer in Frisches legt, legt Leben in Totes), und die Schöpfung von Himmeln und Erde als Größenvergleich (81)."},
 {arab: "كُن فَيَكُون", tr: "kun fa-yakūn", wurzel: "k-w-n", erkl: "„Sei! – und es ist“ (36:82, achtmal im Koran): Allahs Schaffen braucht weder Material noch Mühe noch Zeit – nur Willen. Der Schlussstein unter jeder Auferstehungs- und Wunderfrage; danach bleibt nur noch 36:83: „Gepriesen sei Der, in Dessen Hand die Herrschaft über alles ist – und zu Ihm werdet ihr zurückgebracht.“"}
],
tafsir: [
 {vers: "Verse 1–12", text: "Schwur beim „weisen Koran“ auf die Gesandtschaft des Propheten ﷺ – gegen die Dauerzweifel Mekkas; dann die bittere Diagnose über die Verstockten: „Wir haben an ihren Hälsen Fesseln angebracht … und vor ihnen eine Sperre und hinter ihnen eine Sperre“ – das Bild des Menschen, der sich durch Gewohnheit und Stolz selbst die Sicht zugemauert hat. Aber Vers 11 definiert die erreichbare Zielgruppe: „Du warnst nur den, der der Ermahnung folgt und den Allerbarmer im Verborgenen fürchtet“ (vgl. 50:33, Lektion 34). Und 36:12 legt das Prinzip der Langzeitwirkung: „Wir schreiben auf, was sie vorausgeschickt haben UND ihre Spuren (āthārahum)“ – auch das, was nach dir weiterwirkt, läuft auf dein Konto: „Wer im Islam eine gute Gepflogenheit beginnt, hat ihren Lohn und den Lohn derer, die danach handeln“ (Sahih Muslim, Nr. 1017)."},
 {vers: "Verse 13–32: die Stadt und ihr Läufer", text: "Zwei Gesandte, verstärkt durch einen dritten – die Stadt droht mit Steinigung. Da „kam vom äußersten Ende der Stadt ein Mann gelaufen“: Er argumentiert klug (erst die Glaubwürdigkeit der Gesandten – „sie verlangen keinen Lohn“ –, dann das eigene Bekenntnis als Einladung: „Warum sollte ICH Dem nicht dienen, Der mich erschaffen hat?“), stellt die Ohnmacht der Götzen bloß und bekennt öffentlich: „Ich glaube an euren Herrn, so hört auf mich!“ – Sie töten ihn (so die Mufassirūn einhellig zum knappen Text). „Es wurde gesagt: Tritt ein ins Paradies! Er sagte: O wüsste doch mein Volk, dass mein Herr mir vergeben hat …“ – Ibn Kathīr zitiert dazu: Er wünschte seinem Volk Gutes lebend und tot. DAS ist das Herz eines Dāʿī: kein Groll, selbst gegen die eigenen Mörder, nur der Wunsch, sie möchten sehen, was er sieht. Das Volk selbst wird mit einem einzigen Schrei erledigt – „und es war nur EIN Schrei, da waren sie erloschen (chāmidūn)“ – gefolgt vom traurigsten Stoßseufzer des Korans: „O schade um die Diener (yā ḥasratan ʿalā l-ʿibād)! Kein Gesandter kommt zu ihnen, ohne dass sie ihn verspotten.“"},
 {vers: "Verse 33–50: das Buch der Zeichen", text: "Vier Zeichen-Tafeln: (1) die tote Erde – „Wir machen sie lebendig und bringen Korn hervor … damit sie von seinen Früchten essen – und das haben nicht ihre Hände gemacht (wa-mā ʿamilat-hu aidīhim). Wollen sie denn nicht dankbar sein?“ (2) die Paare in allem, „was die Erde wachsen lässt, in ihnen selbst und in dem, was sie nicht kennen“ – eine offene Tür für alles spätere Wissen; (3) Nacht/Tag und die Bahnen von Sonne und Mond; (4) das „beladene Schiff“ als Erinnerung an die Arche und an jede Seefahrt: „Wenn Wir wollen, lassen Wir sie ertrinken – ohne Schrei und ohne Rettung, außer als Barmherzigkeit von Uns.“ As-Saʿdī: Die Zeichen sind bewusst Alltagszeichen – Brot, Nachtschlaf, Schifffahrt: Der Koran will, dass dich dein NORMALER Tag an Allah erinnert, nicht erst das Spektakel. Dazwischen die zwei Verweigerungen der Mekkaner: beim Jenseits („Wann wird dieses Versprechen wahr?“) und beim Sozialen – auf „Gebt von dem aus, womit Allah euch versorgt hat“ antworten sie: „Sollen wir den speisen, den Allah hätte speisen können, wenn Er wollte?“ (36:47) – das zynischste Anti-Sadaqa-Argument aller Zeiten, vom Koran für alle Zeiten dokumentiert."},
 {vers: "Verse 51–83: Posaune, Salām und die Knochen-Frage", text: "Der Posaunenstoß, das Eilen aus den Gräbern („Wer hat uns von unserer Schlafstätte auferweckt?“), die exakte Gerechtigkeit („Heute wird keiner Seele Unrecht getan, und euch wird nur vergolten, was ihr zu tun pflegtet“) – und die Paradies-Szene mit dem Gipfel salāmun qaulan min rabbin raḥīm. Gegenschnitt: „Sondert euch heute ab, ihr Übeltäter!“ und die Zeugenschaft des Körpers: „Heute versiegeln Wir ihre Münder, und ihre Hände sprechen zu Uns, und ihre Füße bezeugen, was sie erworben haben“ (36:65). Dann die ʿAqīda-Klarstellung gegen die Dichter-Vorwürfe („Wir haben ihn nicht das Dichten gelehrt, und es ziemt ihm nicht“) – und das Finale um den morschen Knochen mit der dreifachen Antwort und kun fa-yakūn. Al-Qurṭubī zum Schluss-Tasbīḥ (83): Die Sure, die mit dem Zweifel der Menschen begann, endet mit der Hand, „in der die Herrschaft über alles ist“ – zwischen diesen beiden Polen spielt jedes Menschenleben."}
],
ahadith: [
 {text: "„Wer im Islam eine gute Gepflogenheit ins Leben ruft, erhält ihren Lohn und den Lohn derer, die nach ihm danach handeln, ohne dass deren Lohn gemindert würde …“ – zum āthār-Prinzip von 36:12.", quelle: "Sahih Muslim, Nr. 1017"},
 {text: "„Wenn der Mensch stirbt, enden seine Taten außer dreien: fortlaufende Sadaqa, Wissen, von dem (weiter) profitiert wird, oder ein rechtschaffenes Kind, das für ihn betet.“ – die ‚Spuren', die weiterlaufen.", quelle: "Sahih Muslim, Nr. 1631"},
 {text: "Zur Ehrlichkeit über die Suren-Vorzüge: Der verbreitete Hadith „Alles hat ein Herz, und das Herz des Korans ist Yā-Sīn“ (at-Tirmidhī, Nr. 2887) ist nach dem Urteil der Hadith-Kritiker schwach (ḍaʿīf) – die Größe der Sure steht davon unabhängig durch ihren Inhalt fest.", quelle: "at-Tirmidhī, Nr. 2887 (ḍaʿīf; vgl. al-Albānī, Ḍaʿīf at-Tirmidhī)"},
 {text: "„Am Tag der Auferstehung werden Siegel auf die Münder gelegt, und der Oberschenkel und die Glieder sprechen über seine Taten“ – der Sunna-Kommentar zu 36:65.", quelle: "Sahih Muslim, Nr. 2969 (sinngemäß)"}
],
hanafi: null,
umsetzung: [
 "Arbeite an deinen āthār (36:12): Beginne EINE Sache, die ohne dich weiterläuft – ein Lernkreis, eine Dauerspende, ein nützlicher Inhalt, ein Kind, dem du Koran beibringst. Dein Konto läuft dann auch, wenn du schläfst – und nach dem Tod.",
 "Lerne vom Läufer der Stadt: Du brauchst kein Amt, um die Wahrheit zu verteidigen – aber seine Methode beachten: zuerst Glaubwürdigkeit („sie verlangen nichts“), dann das persönliche Zeugnis („warum sollte ICH nicht…“). So baust du jedes Daʿwa-Gespräch.",
 "Mache den Alltags-Zeichen-Spaziergang (36:33 ff.): eine Woche lang täglich EIN Normal-Zeichen bewusst verdanken – Brot, Schlaf, Sonne, Verkehrsmittel. „Nicht ihre Hände haben es gemacht.“",
 "Bei jeder ‚unmöglichen' Lage – Krankheit, verfahrene Familie, große Ziele – rezitiere 36:82–83 und meine es: kun fa-yakūn. Duʿā zu Dem, Der so erschafft, kennt keine hoffnungslosen Fälle.",
 "Sei ehrlich mit Hadith-Qualität (wie diese Lektion beim ‚Herz des Korans'): Prüfe Vorzugs-Hadithe, bevor du sie weitergibst – Liebe zur Sunna zeigt sich in Sorgfalt, nicht in Weiterleitungs-Eifer."
]
},

// ───────────────────────── Lektion 42: Al-Furqān ─────────────────────────
{
sure: 25, offb: 42, name: "Al-Furqān", arab: "سُورَةُ الْفُرْقَانِ", de: "Die Unterscheidung", verse: 77, ort: "Mekka",
zeit: "Mittelmekkanisch – Antwort auf die Einwände-Liste der Quraisch und Charta der „Diener des Allerbarmers“",
kurz: "Die Sure der Einwände und der Antworten. Die Quraisch hatten eine ganze Liste: Warum isst dieser Gesandte und geht auf Märkte? Warum kommt kein Engel mit ihm herab? Warum wird der Koran nicht auf einmal herabgesandt? Die Sure nimmt jeden Einwand auf – und dreht ihn: Gesandte waren immer Menschen, „die Speise aßen und auf den Märkten gingen – und Wir machen die einen von euch für die anderen zur Prüfung: Werdet ihr standhaft sein?“ Der Koran kommt stückweise, „damit Wir dein Herz damit festigen“ (25:32 – der Vers, auf dem der rote Faden dieser App beruht!). Und sie warnt vor dem Tag der falschen Freunde: „O wehe mir, hätte ich doch nicht den Soundso zum Freund genommen!“ Ihr Finale ist das berühmteste Charakterprofil des Korans: die ʿIbād ar-Raḥmān (25:63–77) – wie sie gehen, schlafen, ausgeben, bereuen und beten. Vierzehn Eigenschaften, die du als Checkliste deiner Tazkiya nutzen kannst – mit dem Tauba-Versprechen der Superlative mittendrin: Allah wandelt die schlechten Taten der aufrichtig Umkehrenden „in gute Taten um“ (25:70).",
schluessel: {arab: "وَعِبَادُ الرَّحْمَٰنِ الَّذِينَ يَمْشُونَ عَلَى الْأَرْضِ هَوْنًا وَإِذَا خَاطَبَهُمُ الْجَاهِلُونَ قَالُوا سَلَامًا", ueb: "Die Diener des Allerbarmers sind diejenigen, die demütig auf der Erde gehen – und wenn die Unwissenden sie anreden, sagen sie: „Frieden!“", ref: "25:63"},
kontext: ["Furqān – „die Unterscheidung“ – ist ein Name des Korans (25:1): das Buch, das Wahrheit von Lüge trennt (vgl. qaul faṣl, Lektion 36). Die Sure dokumentiert den Propaganda-Katalog Mekkas fast vollständig: „selbstersonnene Lüge mit fremder Hilfe“ (25:4), „Fabeln der Früheren, die er sich aufschreiben ließ“ (25:5), der Menschlichkeits-Einwand (25:7), der Engel-Wunsch (25:21) – und beantwortet sie nicht mit Beleidigtsein, sondern mit Argument und Gegenbild.",
"Zu 25:27–29 („Am Tag, da der Ungerechte sich in die Hände beißt … O wehe mir, hätte ich doch nicht den Soundso zum Freund genommen – er hat mich vom Gedenken abirren lassen, nachdem es zu mir gekommen war“) überliefern die Tafsir-Werke den Anlass: ʿUqba ibn Abī Muʿaiṭ hatte dem Propheten ﷺ bereits zugeneigt – da stellte ihn sein Freund Ubayy ibn Chalaf zur Rede und verlangte als Beweis der Treue, den Propheten ﷺ öffentlich zu demütigen; ʿUqba gehorchte seinem ‚Freund' und starb im Unglauben (Standardbericht bei al-Wāḥidī und Ibn Kathīr zu 25:27; die Warnung gilt nach dem Wortlaut jeder zerstörerischen Freundschaft). Die Sunna fasst es positiv: „Der Mensch folgt der Religion seines engen Freundes – so schaue jeder von euch, wen er zum engen Freund nimmt“ (Abū Dāwūd, Nr. 4833; at-Tirmidhī, Nr. 2378; hasan).",
"Der Schlussteil (63–77) wurde zum klassischen Tazkiya-Lehrplan: Die Gelehrten ließen Schüler die vierzehn Eigenschaften auswendig lernen und monatsweise einüben. Beachte die Reihenfolge: Sie beginnt beim GANG (dem Außenbild der Demut) und endet beim GEBET um gottesfürchtige Nachkommen (der Generationenverantwortung) – Tazkiya vom ersten Schritt bis zur Familiengründung."],
asbab: [
 {text: "25:27–29: der Fall ʿUqba ibn Abī Muʿaiṭ, der auf Druck seines Freundes Ubayy ibn Chalaf vom bereits angenommenen Weg abließ – „hätte ich doch nicht den Soundso zum Freund genommen!“", quelle: "al-Wāḥidī, Asbāb an-Nuzūl; Tafsir Ibn Kathīr zu 25:27 (Standardbericht der Tafsir-Literatur)"},
 {text: "25:32 („Warum wurde der Koran nicht als Ganzes auf einmal herabgesandt?“): Einwand der Quraisch – mit Allahs Antwort: „So (machen Wir es), um dein Herz damit zu festigen, und Wir haben ihn wohlgeordnet vorgetragen.“", quelle: "Koranischer Selbstbericht; vgl. Tafsir aṭ-Ṭabarī z. St."}
],
begriffe: [
 {arab: "الْفُرْقَان", tr: "al-furqān", wurzel: "f-r-q", erkl: "„Die Unterscheidung“ – Name des Korans (und der Tora, 2:53; auch der Badr-Tag heißt yaum al-furqān, 8:41): das Kriterium, das Wahr und Falsch scheidet. Wer den Furqān hat und trotzdem alles ‚irgendwie gleich gültig' findet, benutzt ihn nicht."},
 {arab: "بُورًا", tr: "būrā", wurzel: "b-w-r", erkl: "25:18: „… ein Volk des Verderbens (qauman būrā)“ – von bāra: brachliegen, verrotten. Menschen, die durch Dauer-Wohlstand und Vergessen innerlich ‚brachgefallen' sind: das Gegenteil von Tazkiya (Wachstum durch Pflege)."},
 {arab: "هَبَاء مَّنثُورًا", tr: "habāʾan manthūrā", wurzel: "h-b-w / n-th-r", erkl: "25:23: „Und Wir wenden uns dem zu, was sie an Werken getan haben, und machen es zu verstreutem Staub.“ – Taten ohne Iman und Ichlāṣ: optisch beeindruckend, am Gerichtstag Schwebstaub im Licht. Der Angst-Vers der Aufrichtigen – und der Grund, warum Absichts-Arbeit (Lektion 14, 30) vor Mengen-Arbeit kommt."},
 {arab: "هَوْنًا", tr: "haunan", wurzel: "h-w-n", erkl: "„Demütig/gelassen (gehen)“ (25:63) – haun: sanfte Würde ohne Gepolter und ohne Kriechen. Die erste ʿIbād-ar-Raḥmān-Eigenschaft ist eine GANGART: Tazkiya wird sichtbar, bevor du ein Wort sagst."},
 {arab: "قَالُوا سَلَامًا", tr: "qālū salāmā", wurzel: "s-l-m", erkl: "„… sagen sie: Frieden!“ – die Deeskalations-Formel gegenüber Provokateuren (dschāhilūn): kein Rückzug aus Schwäche, sondern Souveränität (vgl. hadschr dschamīl, Lektion 3). Al-Ḥasan al-Baṣrī: „Sie sind milde zu den Toren – auch wenn man sie reizt.“"},
 {arab: "لَمْ يُسْرِفُوا وَلَمْ يَقْتُرُوا", tr: "lam yusrifū wa-lam yaqturū", wurzel: "s-r-f / q-t-r", erkl: "25:67: „die, wenn sie ausgeben, weder maßlos noch knauserig sind – dazwischen gibt es einen mittleren Stand (qawām)“. Die Finanz-Eigenschaft der ʿIbād ar-Raḥmān: Der Koran heiligt weder Konsum noch Askese, sondern das tragfähige Mittelmaß."},
 {arab: "يُبَدِّلُ اللَّهُ سَيِّئَاتِهِمْ حَسَنَات", tr: "yubaddilu llāhu sayyiʾātihim ḥasanāt", wurzel: "b-d-l", erkl: "25:70: Wer bereut, glaubt und rechtschaffen handelt – „denen wandelt Allah ihre schlechten Taten in gute um“. Nach der stärksten Deutung (mit dem Muslim-Hadith unten): Die Sünden selbst werden am Gerichtstag in Gutschriften verwandelt. Der großzügigste Satz des Vergebungsrechts."},
 {arab: "قُرَّة أَعْيُن", tr: "qurrata aʿyun", wurzel: "q-r-r", erkl: "25:74: „Unser Herr, schenke uns an unseren Gattinnen und Nachkommen Grund zur Augenfreude (qurrata aʿyun), und mache uns für die Gottesfürchtigen zum Vorbild (imāman).“ – DAS Familien-Duʿā des Korans: Es bittet nicht um perfekte Umstände, sondern um eine Familie, an der das Auge zur Ruhe kommt – und setzt das Ziel frech hoch: Vorbild der Muttaqīn."}
],
tafsir: [
 {vers: "Verse 1–20: die Einwände", text: "Eröffnung mit tabāraka („Segensreich ist Der, Der den Furqān herabgesandt hat … Dem die Herrschaft gehört, Der sich kein Kind genommen hat und keinen Teilhaber“) – dann die Einwände-Liste und ihre Entkräftung. Kernantwort 25:20: „Wir sandten vor dir keine Gesandten, die nicht Speise aßen und auf den Märkten umhergingen.“ Prophetie widerspricht nicht der Menschlichkeit – sie adelt sie: Das Vorbild MUSS unter Alltagsbedingungen leben, sonst wäre es keins. Und der Zusatz, der dein Sozialleben erklärt: „Wir machen die einen von euch für die anderen zur Prüfung (fitna) – werdet ihr standhaft sein? Und dein Herr sieht sehr wohl.“ – Der Arme prüft den Reichen, der Chef den Angestellten, der schwierige Verwandte dich: Menschen sind füreinander Prüfungsmaterial, by design."},
 {vers: "Verse 21–44: falsche Freunde und das Herz des Propheten", text: "Der Tag des Händebeißens (25:27–29, Anlass oben) mit der zeitlosen Freundes-Warnung – „der Satan lässt den Menschen (dann) im Stich“. Dazwischen die einzige Klage des Propheten ﷺ, die der Koran wörtlich zitiert: „O mein Herr, mein Volk hat diesen Koran für etwas zu Meidendes genommen (mahdschūrā)“ (25:30) – die Mufassirūn zählen die Formen des hadschr auf: ihn nicht hören, nicht verstehen wollen, nicht danach handeln, nicht mit ihm heilen, ihn nicht weitergeben. Jede Generation muss sich fragen, welche davon ihre ist. Dann 25:32–33, das Fundament dieser App: Der Koran kam stückweise „um dein Herz zu festigen“ – Erziehung geschieht in Dosen, nicht als Datei-Download; „und sie bringen dir kein Gleichnis, ohne dass Wir dir die Wahrheit und eine noch bessere Erklärung brächten“: Jeder Angriff erzeugte eine Offenbarung, die bleibt – die Einwände der Quraisch sind vergessen, die Antworten rezitiert die Welt."},
 {vers: "Verse 45–62: die Zeichen des Allerbarmers", text: "Die Zeichen-Reihe im Ton der Barmherzigkeit: der gedehnte Schatten, der Schlaf als „Ruhe“ und der Tag als „Auferstehung“ (jeder Morgen ist eine Probe-Auferstehung!), die Winde als Boten des Regens, das „reine Wasser, um damit totes Land zu beleben“, die zwei Meere – süß und salzig – mit der Schranke (barzach) dazwischen, die Verwandtschaft aus Wasser (nasaban wa-ṣihrā). Dazwischen die Haltung des Dāʿī: „Gehorche nicht den Ungläubigen und mühe dich gegen sie damit (bihī – mit dem Koran!) ab, mit großem Einsatz (dschihādan kabīrā)“ (25:52) – der ‚große Dschihād' dieses Verses ist ausdrücklich der mit dem ARGUMENT des Korans, nicht mit der Waffe: der Kampf um Herzen durch Rezitation, Erklärung, Geduld. Und 25:58 gibt die Kraftquelle: „Verlass dich auf den Lebendigen, Der nicht stirbt.“"},
 {vers: "Verse 63–77: die ʿIbād ar-Raḥmān", text: "Das Profil in Paaren: (1) Gang in Demut + Salām gegen Provokation (Sozialverhalten). (2) Nächte „in Niederwerfung und Stehen“ + Furcht vor Dschahannam trotz allem (Gottesbeziehung – sie beten nachts UND halten sich nicht für sicher). (3) Mitte beim Ausgeben (Finanzen). (4) Die drei Großsünden-Absagen: kein Schirk, kein Töten, keine Unzucht – mit der Tauba-Tür und dem Tausch-Versprechen 25:70; dazu der Hadith vom letzten Mann, dessen kleine Sünden vorgelesen werden und der schon zittert wegen der großen – da heißt es: „Für jede schlechte Tat hast du eine gute“ – bis er selbst ruft: „Ich habe Dinge getan, die ich hier nicht sehe!“ – und der Prophet ﷺ lachte, dass seine Backenzähne sichtbar wurden (Sahih Muslim, Nr. 190). (5) Kein Falschzeugnis, würdevolles Vorbeigehen am Nichtigen (laġw), waches Hören der Zeichen („sie fallen nicht taub und blind darüber her“ – auch Fromme können Koran ‚konsumieren' ohne Hinhören!). (6) Das Familien-Duʿā 25:74. Lohn: „Ihnen wird der hohe Rang (al-ġurfa) vergolten, weil sie standhaft waren, und ihnen wird darin Gruß und Friede entgegengebracht.“ – Als-Saʿdī: Vierzehn Eigenschaften, keine davon spektakulär – zusammen ergeben sie den Menschen, nach dem sich der Allerbarmer selbst benennt: ʿibād AR-RAḤMĀN."}
],
ahadith: [
 {text: "„Der Mensch folgt der Religion seines engen Freundes (chalīl) – so schaue jeder von euch, wen er sich zum engen Freund nimmt.“ – die Sunna zu 25:28.", quelle: "Sunan Abū Dāwūd, Nr. 4833; at-Tirmidhī, Nr. 2378; hasan"},
 {text: "Der Hadith vom Mann, dessen Sünden in gute Taten verwandelt werden, bis er selbst nach weiteren fragt – der Prophet ﷺ lachte dabei: der Sunna-Beleg zu 25:70.", quelle: "Sahih Muslim, Nr. 190"},
 {text: "„Das gute und das schlechte Sitzungs-Umfeld sind wie der Moschusträger und der Blasebalg-Schmied …“ – Freundeswahl als Duft- oder Brandfrage.", quelle: "Sahih al-Buchari, Nr. 5534; Sahih Muslim, Nr. 2628"},
 {text: "ʿĀʾischa über das Nachtgebet des Propheten ﷺ (zur Eigenschaft 25:64) – lange Stände, Weinen, „soll ich nicht ein dankbarer Diener sein?“", quelle: "Sahih al-Buchari, Nr. 4837; Sahih Muslim, Nr. 2819"}
],
hanafi: "25:60 ist ein Sadschda-Vers: „Und wenn zu ihnen gesagt wird: Werft euch vor dem Allerbarmer nieder!, sagen sie: Was ist denn der Allerbarmer? … und es mehrt ihre Abneigung.“ Nach hanafitischer Schule ist die Tilāwa-Sadschda hier – wie bei allen 14 Sadschda-Versen der Schule – wādschib für den, der den Vers rezitiert oder hört. Der Vers ist zugleich die perfekte Brücke zum Schlussteil: Die Leugner verweigern dem Raḥmān die Niederwerfung – die ʿIbād ar-Raḥmān (25:63 ff.) verbringen ihre Nächte „in Niederwerfung und Stehen“. Deine Sadschda an dieser Stelle ist die Antwort auf ihre Frage.",
umsetzung: [
 "Mache 25:63–77 zu deinem Tazkiya-Lehrplan für ein Jahr: 14 Eigenschaften, pro Monat eine bewusst trainieren (Gang, Salām-Antwort, Nachtgebet, Mittelmaß im Geld, die drei Absagen, wahres Zeugnis, Umgang mit laġw, waches Koran-Hören, Familien-Duʿā …). Das ist der klassische Weg der Gelehrten mit diesem Abschnitt.",
 "Auditiere deine Freundschaften mit 25:28 + Abū Dāwūd 4833: Wer zieht dich messbar zu Allah, wer messbar weg? Konsequenz ziehen – ʿUqba starb am falschen Freund.",
 "Prüfe dich auf hadschr al-Qurʾān (25:30): Welche der fünf Meide-Formen (nicht hören, nicht verstehen, nicht handeln, nicht heilen, nicht weitergeben) ist deine? Diese App schließt die Verstehens-Lücke – schließe du die Handlungs-Lücke.",
 "Lerne das Familien-Duʿā 25:74 auswendig (rabbanā hab lanā min azwādschinā wa-dhurriyyātinā qurrata aʿyun wa-dschʿalnā li-l-muttaqīna imāmā) – bete es täglich, ob verheiratet oder nicht: Es baut an deiner Zukunft.",
 "Verinnerliche 25:70 gegen die Verzweiflungs-Einflüsterung (vgl. Lektion 21): Deine Vergangenheit kann per aufrichtiger Tauba zur Gutschrift werden – mit Sahih-Muslim-Beleg. Niemand ist ‚zu weit weg'."
]
}
];
